package com.guocheng.mediapocket;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;
final class HomeSources {
 static JSONArray list(Context c)throws Exception{try(InputStream in=c.getAssets().open("public-home-sources.json")){return new JSONArray(new String(CoverFiles.read(in,256*1024),"UTF-8"));}}
 static JSONObject selected(JSONArray definitions,String id)throws Exception{for(int i=0;i<definitions.length();i++){JSONObject d=definitions.getJSONObject(i);if(id.equals(d.optString("id")))return d;}return definitions.getJSONObject(0);}
 static JSONArray cmsSites(Context c)throws Exception{JSONArray result=new JSONArray(),definitions=list(c);for(int i=0;i<definitions.length();i++){JSONObject d=definitions.getJSONObject(i);if(!d.optString("kind").equals("cms"))continue;result.put(new JSONObject().put("key",d.getString("key")).put("name",d.getString("name")+" · 公开源").put("type",3).put("api",CmsApi.MARKER).put("jar","").put("searchable",1).put("quickSearch",1).put("filterable",0).put("public.status",d.optString("status")).put("ext",new JSONObject().put("api",d.getString("url"))));}return result;}
 static JSONObject merge(Context c,JSONObject config)throws Exception{return RetiredSourceRules.clean(config);}
 static FusionCatalog.Session session(Context c,String id)throws Exception{JSONArray definitions=list(c);if(definitions.length()==0){if(c.getSharedPreferences("data",0).getString("tvbox.active","").isEmpty())throw new IOException("尚未配置影视仓接口，请先添加接口");return FusionCatalog.session(c,"","");}JSONObject source=selected(definitions,id);String kind=source.optString("kind");if(kind.equals("config"))return FusionCatalog.session(c,source.getString("url"),"");if(kind.equals("cms"))return FusionCatalog.session(c,"",source.getString("key"));return FusionCatalog.session(c,"","");}
 static String status(Context c,String id)throws Exception{return selected(list(c),id).optString("status");}
 /** 已下线公开源的目录缓存。文件索引很小，每次启动都清；偏好里的那份仍只在第一次 seed 时扫。 */
 static void pruneRetiredCaches(Context c){try{CacheFiles.of(c).removeIf(RetiredSourceRules::cacheKey);}catch(Exception ignored){}}
 static void seed(Context c){SharedPreferences p=c.getSharedPreferences("data",0);pruneRetiredCaches(c);if(p.getBoolean("home.noPresets.v1",false))return;try{SharedPreferences.Editor e=p.edit();for(Map.Entry<String,?> item:p.getAll().entrySet()){String key=item.getKey();if(key.startsWith("tvbox.config:")&&item.getValue() instanceof String){try{e.putString(key,RetiredSourceRules.clean(new JSONObject((String)item.getValue())).toString());}catch(Exception ignored){}}else if(key.startsWith("fusion.site:")&&RetiredSourceRules.site(String.valueOf(item.getValue())))e.remove(key);else if(RetiredSourceRules.cacheKey(key))e.remove(key);}
 JSONArray profiles=RetiredSourceRules.profiles(new JSONArray(p.getString("tvbox.profiles","[]")));if(RetiredSourceRules.profile(p.getString("tvbox.active","")))e.remove("tvbox.active");for(String key:p.getAll().keySet())if(key.contains("https://raw.githubusercontent.com/qist/tvbox/master/fty.json")&&(key.startsWith("tvbox.config:")||key.startsWith("fusion.")))e.remove(key);e.putString("tvbox.profiles",profiles.toString()).putString("home.source.v1","current").putString("fusion.homeProvider","stremio").putBoolean("home.noPresets.v1",true).apply();}catch(Exception ignored){}}
}
